<script setup>import{useForm,Link}from'@inertiajs/vue3';import AdminLayout from'../../../Layouts/AdminLayout.vue';const props=defineProps({product:Object,categories:Array,brands:Array,aiFormatterEnabled:Boolean});const p=props.product||{};const form=useForm({category_id:p.category_id||'',brand_id:p.brand_id||'',name:p.name||'',slug:p.slug||'',sku:p.sku||'',short_description:p.short_description||'',description:p.description||'',price:p.price||'',sale_price:p.sale_price||'',stock_quantity:p.stock_quantity??0,low_stock_threshold:p.low_stock_threshold??5,track_stock:p.track_stock??true,condition:p.condition||'new',status:p.status||'draft',featured:p.featured??false,merchant_sync_enabled:p.merchant_sync_enabled??true,primary_image:null,primary_image_url:'',gallery:[],gallery_urls:'',gtin:p.gtin||'',mpn:p.mpn||'',google_product_category:p.google_product_category||'',product_type:p.product_type||'',warranty:p.warranty||'',specifications_text:p.specifications?Object.entries(p.specifications).map(([k,v])=>`${k}: ${v}`).join('\n'):'',meta_title:p.meta_title||'',meta_description:p.meta_description||'',sort_order:p.sort_order||0});const submit=()=>p.id?form.patch(`/admin/products/${p.slug}`,{forceFormData:true}):form.post('/admin/products',{forceFormData:true});</script><template><AdminLayout><div class="flex items-center justify-between"><div><p class="section-kicker">Catalogue</p><h1 class="section-title">{{p.id?'Edit product':'Add product'}}</h1></div><Link href="/admin/products" class="btn-light">Back</Link></div><form class="mt-6 grid gap-5 lg:grid-cols-[1fr_340px]" @submit.prevent="submit"><div class="grid gap-5"><section class="card p-5"><h2 class="font-black">Product information</h2><div class="mt-4 grid gap-4 sm:grid-cols-2"><div class="sm:col-span-2"><label class="label">Product name</label><input v-model="form.name" class="input"><p class="error">{{form.errors.name}}</p></div><div><label class="label">SKU</label><input v-model="form.sku" class="input"></div><div><label class="label">Category</label><select v-model="form.category_id" class="input"><option value="">Select</option><option v-for="c in categories" :key="c.id" :value="c.id">{{c.name}}</option></select></div><div><label class="label">Brand</label><select v-model="form.brand_id" class="input"><option value="">No brand</option><option v-for="b in brands" :key="b.id" :value="b.id">{{b.name}}</option></select></div><div><label class="label">Price</label><input v-model="form.price" type="number" class="input"></div><div><label class="label">Sale price</label><input v-model="form.sale_price" type="number" class="input"></div><div><label class="label">Stock</label><input v-model="form.stock_quantity" type="number" class="input"></div><div><label class="label">Low stock alert</label><input v-model="form.low_stock_threshold" type="number" class="input"></div><div class="sm:col-span-2"><label class="label">Short description</label><textarea v-model="form.short_description" class="input" rows="3"></textarea></div><div class="sm:col-span-2"><label class="label">Description</label><textarea v-model="form.description" class="input" rows="10"></textarea></div><div class="sm:col-span-2"><label class="label">Specifications <span class="text-xs text-slate-400">one per line: Label: Value</span></label><textarea v-model="form.specifications_text" class="input font-mono" rows="7"></textarea></div></div></section><section class="card p-5"><h2 class="font-black">Images & Merchant data</h2><div class="mt-4 grid gap-4 sm:grid-cols-2"><div><label class="label">Main image</label><input type="file" accept="image/*" @change="form.primary_image=$event.target.files[0]"></div><div><label class="label">Or image URL</label><input v-model="form.primary_image_url" class="input"></div><div><label class="label">GTIN</label><input v-model="form.gtin" class="input"></div><div><label class="label">MPN</label><input v-model="form.mpn" class="input"></div><div><label class="label">Warranty</label><input v-model="form.warranty" class="input"></div><div><label class="label">Product type</label><input v-model="form.product_type" class="input"></div></div></section></div><aside class="card h-fit p-5"><h2 class="font-black">Publishing</h2><div class="mt-4 grid gap-4"><div><label class="label">Status</label><select v-model="form.status" class="input"><option value="draft">Draft</option><option value="active">Active</option><option value="archived">Archived</option></select></div><div><label class="label">Condition</label><select v-model="form.condition" class="input"><option value="new">New</option><option value="refurbished">Refurbished</option><option value="used">Used</option></select></div><label class="flex gap-2 text-sm"><input v-model="form.track_stock" type="checkbox"> Track stock</label><label class="flex gap-2 text-sm"><input v-model="form.featured" type="checkbox"> Featured</label><label class="flex gap-2 text-sm"><input v-model="form.merchant_sync_enabled" type="checkbox"> Google Merchant sync</label><button class="btn-primary" :disabled="form.processing">Save product</button></div></aside></form></AdminLayout></template>
